class Solution {
    public long countPairsWithin(int[] mains, int[] sides, int budget) {
        long total = 0;
        for (int x : mains) {
            long cap = (long) budget - x;
            int lo = 0, hi = sides.length;
            while (lo < hi) { int mid = (lo + hi) >>> 1; if (sides[mid] <= cap) lo = mid + 1; else hi = mid; }
            total += lo;
        }
        return total;
    }
}

