class Solution:
    def countPairsWithin(self, mains: List[int], sides: List[int], budget: int) -> int:
        total, j = 0, len(sides) - 1
        for x in mains:
            while j >= 0 and x + sides[j] > budget:
                j -= 1
            total += j + 1
        return total

