class Solution {
    public long countPairsWithin(int[] mains, int[] sides, int budget) {
        long total = 0;
        int j = sides.length - 1;
        for (int x : mains) {
            while (j >= 0 && (long) x + sides[j] > budget) j--;
            total += j + 1;
        }
        return total;
    }
}

